"""Build the auto-generated dataset catalog (CATALOG.md) for facilities/.

usage: python -I -X utf8 make_catalog.py <facilities_dir>
Reads utf8/<ID>/*.csv plus the _sum_* download summaries and kric_catalog.tsv.
"""
import csv
import glob
import html
import io
import json
import os
import re
import sys

import requests

UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0 Safari/537.36"
COORD = re.compile(r"위도|경도|WKT|POINT|LINESTRING|좌표|lat|lon|X좌표|Y좌표", re.I)


def load_meta(base):
    meta = {}
    for p in glob.glob(os.path.join(base, "_sum_*.json")):
        for e in json.load(open(p, encoding="utf-8")):
            if "oa" in e:
                meta.setdefault(e["oa"], {}).update(
                    title=e.get("title"), url=e.get("url"), updated=(e.get("dates") or [""])[0])
            elif "pk" in e:
                meta[f"DG-{e['pk']}"] = dict(title=e.get("title"), url=e.get("url"),
                                             updated=(e.get("updtDt") or "")[:10], basis=e.get("stdrDe"),
                                             operator=e.get("insttNm"), desc=e.get("desc"))
    p = os.path.join(base, "_sum_kric.jsonl")
    kcat = {}
    cp = os.path.join(base, "raw", "kric_catalog.tsv")
    if os.path.exists(cp):
        for line in open(cp, encoding="utf-8"):
            parts = line.rstrip("\n").split("\t")
            if len(parts) >= 3:
                m = re.search(r"수정일 : ([\d.]+)", parts[2])
                kcat[parts[0]] = (parts[1], m.group(1) if m else "")
    if os.path.exists(p):
        for line in open(p, encoding="utf-8"):
            e = json.loads(line)
            t, d = kcat.get(e["id"], ("", ""))
            meta[f"KRIC-{e['id']}"] = dict(title=t, url=e["url"], updated=d, operator=e.get("provider"),
                                          desc=e.get("desc"))
    return meta


def seoul_page_meta(base, oa, s):
    p = os.path.join(base, "raw", oa, "_page.html")
    if not os.path.exists(p):
        try:
            t = s.get(f"https://data.seoul.go.kr/dataList/{oa}/S/1/datasetView.do", timeout=60).text
            os.makedirs(os.path.dirname(p), exist_ok=True)
            open(p, "w", encoding="utf-8").write(t)
        except Exception:  # noqa: BLE001
            return {}
    t = open(p, encoding="utf-8").read()
    m1 = re.search(r'<meta name="title" content="([^"]*)"', t)
    m2 = re.search(r"데이터 갱신일</th>\s*<td><span class=\"en\">([^<]*)<", t)
    m3 = re.search(r"제공부서</th>\s*<td>([^<]*)<", t)
    m4 = re.search(r"저작권자</th>\s*<td>([^<]*)<", t)
    return dict(title=html.unescape(m1.group(1)) if m1 else "", updated=m2.group(1) if m2 else "",
                operator=(m4.group(1).strip() if m4 else "") + (" / " + m3.group(1).strip() if m3 else ""))


def read_table(path):
    rows = list(csv.reader(io.StringIO(open(path, encoding="utf-8").read())))
    rows = [r for r in rows if any(c.strip() for c in r) and not r[0].startswith("## sheet")]
    hi = 0
    for i, r in enumerate(rows[:15]):
        if sum(1 for c in r if c.strip()) >= 4:
            hi = i
            break
    header = [c.strip().replace("\n", " ") for c in rows[hi]] if rows else []
    while header and not header[-1]:
        header.pop()
    data = rows[hi + 1:]
    return header, data


def main():
    base = sys.argv[1]
    s = requests.Session()
    s.headers["User-Agent"] = UA
    meta = load_meta(base)
    out = ["# Auto-generated catalog of downloaded tables", "",
           "Generated by `../tools/make_catalog.py`. One section per dataset; for each file: rows "
           "(after the detected header row; multi-sheet xlsx and title rows make this approximate), columns, "
           "whether a coordinate column was detected, and 3 sample rows.", ""]
    for d in sorted(glob.glob(os.path.join(base, "utf8", "*"))):
        did = os.path.basename(d)
        m = dict(meta.get(did, {}))
        if did.startswith("OA-"):
            pm = seoul_page_meta(base, did, s)
            for k, v in pm.items():
                if v and not m.get(k):
                    m[k] = v
            m.setdefault("url", f"https://data.seoul.go.kr/dataList/{did}/S/1/datasetView.do")
        files = sorted(glob.glob(os.path.join(d, "*.csv")))
        if not files:
            continue
        out.append(f"## {did} - {m.get('title') or ''}")
        out.append("")
        out.append(f"- URL: {m.get('url', '')}")
        out.append(f"- Updated: {m.get('updated', '')}" + (f" (data basis {m['basis']})" if m.get("basis") else ""))
        if m.get("operator"):
            out.append(f"- Operator/provider: {m['operator']}")
        if m.get("desc"):
            out.append(f"- Description: {' '.join(str(m['desc']).split())[:400]}")
        out.append(f"- Raw: `raw/{did}/`, UTF-8: `utf8/{did}/`")
        out.append("")
        for f in files:
            try:
                header, data = read_table(f)
            except Exception as e:  # noqa: BLE001
                out.append(f"### `{os.path.basename(f)}` - unreadable: {e!r}")
                continue
            sample_text = " ".join(",".join(r) for r in data[:3])
            has = bool(COORD.search(",".join(header))) or bool(re.search(r"POINT\(|LINESTRING\(", sample_text))
            out.append(f"### `{os.path.basename(f)}`")
            out.append("")
            out.append(f"- Rows: {len(data)}; coordinates: {'YES' if has else 'no (text location only)'}")
            out.append(f"- Columns: {' | '.join(header)}")
            out.append("- Samples:")
            out.append("```")
            for r in data[:3]:
                out.append(",".join(c.replace("\n", " ") for c in r[:len(header) or None])[:400])
            out.append("```")
            out.append("")
    open(os.path.join(base, "CATALOG.md"), "w", encoding="utf-8").write("\n".join(out))
    print(len(out))


if __name__ == "__main__":
    main()
